import heapq

def solve():
    H, W, T = map(int, input().split())
    grid = []
    for _ in range(H):
        grid.append(input().strip())

    # Find start, goal, and candy positions
    start = None
    goal = None
    candies = []

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    # Handle edge cases
    if start == goal:
        return 0

    # If no candies, check if goal is reachable within T moves using BFS
    if len(candies) == 0:
        # BFS to check if goal is reachable within T moves
        visited = [[False] * W for _ in range(H)]
        queue = [(0, start[0], start[1])]
        visited[start[0]][start[1]] = True

        while queue:
            moves, i, j = queue.pop(0)
            if (i, j) == goal:
                if moves <= T:
                    return 0
                else:
                    continue

            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and not visited[ni][nj] and grid[ni][nj] != '#':
                    visited[ni][nj] = True
                    queue.append((moves + 1, ni, nj))

        return -1

    # Use Dijkstra with state (row, col, candy_mask)
    # dist[row][col][mask] = minimum moves to reach (row, col) with candy mask
    # We'll use a dictionary for efficiency

    # Initialize distance dictionary
    dist = {}

    # Priority queue: (moves, row, col, mask)
    pq = [(0, start[0], start[1], 0)]
    dist[(start[0], start[1], 0)] = 0

    # Directions: up, down, left, right
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    max_candies = 0

    # Create a mapping from candy position to index
    candy_pos_to_idx = {}
    for idx, (i, j) in enumerate(candies):
        candy_pos_to_idx[(i, j)] = idx

    while pq:
        moves, i, j, mask = heapq.heappop(pq)

        # If we've exceeded the move limit, skip
        if moves > T:
            continue

        # If we reached the goal, update answer
        if (i, j) == goal:
            # Count number of candies collected
            candies_collected = bin(mask).count('1')
            max_candies = max(max_candies, candies_collected)
            # Don't break since we want to maximize candies
            continue

        # Try all four directions
        for di, dj in directions:
            ni, nj = i + di, j + dj

            # Check bounds
            if 0 <= ni < H and 0 <= nj < W:
                # Check if it's not a wall
                if grid[ni][nj] != '#':
                    new_mask = mask

                    # If the new cell is a candy, add it to mask
                    if grid[ni][nj] == 'o':
                        if (ni, nj) in candy_pos_to_idx:
                            candy_idx = candy_pos_to_idx[(ni, nj)]
                            new_mask |= (1 << candy_idx)

                    new_moves = moves + 1

                    # Only consider if we haven't visited this state with fewer moves
                    state = (ni, nj, new_mask)
                    if state not in dist or dist[state] > new_moves:
                        dist[state] = new_moves
                        heapq.heappush(pq, (new_moves, ni, nj, new_mask))

    # If we didn't find a valid path to goal, return -1
    if max_candies == 0:
        return -1

    return max_candies

